import React, { useState } from 'react';
import { AlertCircle, CheckCircle2 } from 'lucide-react';

const Registration = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');
    
    if (!formData.fullName ||!formData.password||!FormData.email){
            Error('يرجى ملء جميع الحقول المطلوبة');
      return;
    }

    // التحقق من البريد الجامعي كما هو مطلوب في وثيقة المشروع
    const universityDomain = "@univ-constantine2.dz";
    if (!formData.email.endsWith(universityDomain)) {
      setError(` استخدام بريد إلكتروني جامعي ينتهي بـ ${universityDomain}`);
      return;
    }

    if (formData.password.length < 6) {
      setError('كلمة المرور يجب أن تكون 6 أحرف على الأقل');
      return;
    }

    setSuccess(true);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4 text-right" dir="rtl">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-lg p-8 border border-gray-100">
        <h2 className="text-2xl font-bold mb-6 text-center text-slate-800">إنشاء حساب طالب</h2>
        
        {error && (
          <div className="mb-6 p-4 bg-red-50 border-r-4 border-red-500 text-red-700 flex items-center gap-3">
            <AlertCircle size={20} />
            <span className="text-sm font-medium">{error}</span>
          </div>
        )}

        {success && (
          <div className="mb-6 p-4 bg-emerald-50 border-r-4 border-emerald-500 text-emerald-700 flex items-center gap-3">
            <CheckCircle2 size={20} />
            <span className="text-sm font-medium">تم إنشاء الحساب بنجاح!</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-semibold mb-2 text-slate-700">الاسم واللقب</label>
            <input 
              type="text" 
              className="w-full p-3 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              onChange={(e) => setFormData({...formData, fullName: e.target.value})}
            />
          </div>
          
          <div>
            <label className="block text-sm font-semibold mb-2 text-slate-700">البريد الإلكتروني الجامعي</label>
            <input 
              type="email" 
              placeholder="example@univ-constantine2.dz"
              className="w-full p-3 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 text-left"
              onChange={(e) => setFormData({...formData, email: e.target.value})}
            />
          </div>

          <div>
            <label className="block text-sm font-semibold mb-2 text-slate-700">كلمة المرور</label>
            <input 
              type="password" 
              className="w-full p-3 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              onChange={(e) => setFormData({...formData, password: e.target.value})}
            />
          </div>

          <button 
            type="submit"
            className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold hover:bg-blue-700 transition shadow-lg mt-4"
          >
            تأكيد التسجيل
          </button>
        </form>
      </div>
    </div>
  );
};

export default Registration;
